ground: url(../img/sliderArrow.svg) no-repeat center;\r\n}",".slick-list {\n  overflow: hidden;\n}\n\n.slick-track {\n  display: flex;\n  flex-direction: column;\n}\n\n.slick-arrow {\n  font-size: 0;\n  width: 20px;\n  height: 20px;\n}\n\n.slick-prev {\n  background: url(../img/sliderArrow.svg) no-repeat center;\n  transform: rotate(180deg);\n}\n\n.slick-next {\n  background: url(../img/sliderArrow.svg) no-repeat center;\n}\n\n.crumbs ~ .filter {\n  padding: 0;\n}\n\n.crumbs__wrapper {\n  padding: 15px 0;\n}\n\n.crumbs__list {\n  display: flex;\n  align-items: center;\n  gap: 15px;\n  flex-wrap: wrap;\n}\n\n.crumbs__list-item-dots {\n  font-family: \"Trebuchet MS\", sans-serif;\n  font-weight: 400;\n  font-style: normal;\n  color: black;\n  font-size: 14px;\n}\n\n.crumbs__list-item a {\n  font-family: \"Trebuchet MS\", sans-serif;\n  font-weight: 400;\n  font-style: normal;\n  color: black;\n  font-size: 14px;\n}\n.crumbs__list-item a:hover {\n  color: red;\n}\n\n.similar {\n  padding-top: 15px;\n}\n\n.similar__title {\n  font-family: \"Trebuchet MS\", sans-serif;\n  font-weight: 400;\n  font-style: normal;\n  color: black;\n  font-size: 14px;\n  margin-bottom: 20px;\n}\n\n.similar__list {\n  display: grid;\n  grid-template-columns: repeat(auto-fill, minmax(180px, 1fr));\n  gap: 10px;\n  overflow: hidden;\n}\n\n.similar__list-item a {\n  display: flex;\n  flex-direction: column;\n  align-items: center;\n  gap: 10px;\n  margin-bottom: 10px;\n}\n\n.similar__list-item-img {\n  flex: 0 0 180px;\n  max-width: 180px;\n  border: 1px solid #D4D4D4;\n}\n.similar__list-item-img img {\n  max-height: 180px;\n  width: 100%;\n  height: 100%;\n  object-fit: cover;\n  object-position: center;\n}\n\n.similar__list-title {\n  font-family: \"Trebuchet MS\", sans-serif;\n  font-weight: 400;\n  font-style: normal;\n  color: #3077a0;\n  font-size: 14px;\n  text-align: center;\n}\n\n.similar__list-price {\n  font-family: \"Trebuchet MS\", sans-serif;\n  font-weight: 400;\n  font-style: normal;\n  color: black;\n  font-size: 14px;\n  text-align: center;\n}\n\n.details__title {\n  font-family: \"Trebuchet MS\", sans-serif;\n  font-weight: 400;\n  font-style: normal;\n  color: black;\n  font-size: 20px;\n  margin-bottom: 10px;\n}\n\n.details__advertisement-info {\n  display: flex;\n  flex-direction: column;\n  gap: 5px;\n}\n.details__advertisement-info p {\n  font-family: \"Trebuchet MS\", sans-serif;\n  font-weight: 400;\n  font-style: normal;\n  color: black;\n  font-size: 14px;\n}\n.details__advertisement-info p:first-child span {\n  font-family: \"Trebuchet MS\", sans-serif;\n  font-weight: 400;\n  font-style: normal;\n  color: red;\n  font-size: 18px;\n}\n\n.details__advertisement-info {\n  margin-bottom: 15px;\n}\n\n.details__advertisement-view-wrap {\n  display: flex;\n  gap: 20px;\n  align-items: flex-start;\n  margin-bottom: 20px;\n}\n\n.details__advertisement-view {\n  display: flex;\n  align-items: center;\n  gap: 5px;\n  min-width: 0;\n  flex: 1 1 auto;\n}\n\n.details__advertisement-view-list-img {\n  display: flex;\n  flex-direction: column;\n  align-items: center;\n  gap: 5px;\n  min-width: 0;\n  position: relative;\n}\n.details__advertisement-view-list-img .slick-current {\n  opacity: 1;\n  transition: 0.3s ease;\n}\n\n.details__advertisement-view-img-wrap {\n  position: relative;\n  flex: 0 1 620px;\n  min-width: 0;\n}\n\n.video::before {\n  content: \"\";\n  display: block;\n  width: 25px;\n  height: 17px;\n  background: url(../img/icons/youtubeIcon.svg) no-repeat center/cover, #fff;\n  border-radius: 5px;\n  position: absolute;\n  top: 35px;\n  left: 24px;\n  z-index: 4;\n}\n\n.details__advertisement-view-img {\n  border: 2px solid #D4D4D4;\n  border-radius: 5px;\n  height: 480px;\n  min-width: 0;\n  position: relative;\n}\n.details__advertisement-view-img img {\n  width: 100%;\n  height: 100%;\n  object-fit: contain;\n  object-position: center;\n  border-radius: 5px;\n}\n.details__advertisement-view-img .slick-list {\n  height: 100%;\n  min-width: 0;\n}\n.details__advertisement-view-img .slick-track {\n  height: 100%;\n  flex-direction: initial;\n}\n.details__advertisement-view-img .slick-arrow {\n  position: absolute;\n  z-index: 3;\n  width: 40px;\n  height: 54px;\n  opacity: 0.7;\n  background: url(../img/icons/arrow_right.png);\n}\n.details__advertisement-view-img .slick-next {\n  right: -1.5px;\n  top: 200px;\n}\n.details__advertisement-view-img .slick-prev {\n  left: -1.5px;\n  top: 200px;\n  transform: rotate(180deg);\n}\n\n.magnifier {\n  max-width: 24px;\n  max-height: 24px;\n  position: absolute;\n  cursor: pointer;\n  top: 5px;\n  right: 5px;\n}\n.magnifier img {\n  width: 100%;\n  height: 100%;\n  object-fit: cover;\n  object-position: center;\n}\n\n.details__advertisement-view-list-img-item {\n  width: 74px;\n  height: 80px;\n  border: 1px solid #D4D4D4;\n  border-radius: 5px;\n  margin: 5px 0;\n  cursor: pointer;\n  opacity: 0.5;\n  transition: 0.3s ease;\n}\n.details__advertisement-view-list-img-item img {\n  width: 100%;\n  height: 100%;\n  object-fit: cover;\n  object-position: center;\n  border-radius: 5px;\n}\n\n.details__advertisement-view-list-img {\n  flex: 0 0 74px;\n}\n\n.details__advertisement-options {\n  flex: 1 0 220px;\n  padding: 20px 12px;\n  border: 1px solid #D4D4D4;\n  border-radius: 5px;\n}\n\n.details__advertisement-options-view {\n  font-family: \"Trebuchet MS\", sans-serif;\n  font-weight: 400;\n  font-style: normal;\n  color: black;\n  font-size: 14px;\n  margin-bottom: 10px;\n}\n\n.details__advertisement-options-list {\n  display: flex;\n  flex-direction: column;\n  gap: 5px;\n}\n.details__advertisement-options-list li {\n  display: flex;\n  align-items: center;\n  gap: 5px;\n}\n.details__advertisement-options-list li:nth-child(1)::before {\n  flex: 0 0 20px;\n  content: \"\";\n  display: block;\n  height: 20px;\n  background: url(../img/VIP.png) no-repeat center/cover;\n}\n.details__advertisement-options-list li:nth-child(2)::before {\n  flex: 0 0 20px;\